import{_ as o,o as c,c as d,a0 as r}from"./chunks/framework.CNXp-E7Q.js";const p=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),t={name:"reference/cli.md"};function i(a,e,n,l,s,h){return c(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p><code>bupha [--config PATH] &lt;command&gt;</code> — config search: flag → <code>$BUPHA_CONFIG</code> → <code>./bupha.toml</code> → <code>~/.config/bupha/bupha.toml</code>.</p><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h2><ul><li><code>watch</code> — daemon: webhook → queue → worktree → runner → status. Needs <code>secret_env</code> + <code>token_env</code> set (the unit loads <code>~/.config/bupha/env</code>).</li><li><code>init [dir]</code> — <code>dagger init</code> + install the shared module (pinned sha) + write a <code>dag.bupha()</code> delegate with repo name and <code>patch_host</code> filled from <code>git remote</code>.</li><li><code>run [fn]</code> — run the pipeline locally in the configured repo dir.</li><li><code>doctor</code> — check what the loaded config needs on this box (git, repos, runner deps, secrets, tunnel, disk).</li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><ul><li><code>deploy service [--no-start]</code> — write + enable <code>bupha-watch.service</code> (<code>loginctl enable-linger</code> once for boot persistence).</li><li><code>deploy webhook</code> — register <code>&lt;public_url&gt;/hook</code> on every watched repo (exact-URL takeover only).</li><li><code>deploy env</code> — seed <code>~/.config/bupha/env</code> (never overwrites).</li><li><code>deploy check</code> — verify unit, secrets, endpoint, token.</li><li><code>deploy release [--dry-run]</code> — one-time seed: <code>cargo publish</code> in dep order + tag <code>{repo}-v{ver}</code> + push. Needs <code>CARGO_REGISTRY_TOKEN</code>.</li><li><code>destroy service|webhook|worktrees</code> — teardown counterparts.</li></ul>',6)])])}const f=o(t,[["render",i]]);export{p as __pageData,f as default};
